const HTML="<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>FastForge · Judges’ Scorecard</title><meta name=\"description\" content=\"Quickly score five teams across ten criteria, with ratings from zero to three.\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<style>\n:root{font-size:calc(16px + 4pt);font-family:Inter,Arial,sans-serif;color:#152237;background:#f4f6fa;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button{font:inherit;cursor:pointer}main{max-width:1030px;margin:auto;padding:38px 28px 26px}.mast{display:flex;align-items:center;gap:12px;margin-bottom:26px}.mark{background:#155eef;border-radius:12px;width:40px;height:40px;display:grid;place-items:center;color:white}.mast h1{font-size:calc(23px + 4pt);letter-spacing:-.6px;margin:0}.mast p{margin:5px 0 0;color:#5a6c82;font-size:calc(14px + 4pt)}.tabs{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;background:#e6ebf3;border-radius:14px;padding:5px;margin-bottom:22px}.tab{padding:13px 8px;border:0;background:transparent;border-radius:10px;color:#56657a;font-weight:600}.tab[aria-selected=\"true\"]{background:white;box-shadow:0 2px 5px #19294910;color:#155eef}.card{background:white;border:1px solid #e1e7f0;border-radius:18px;overflow:hidden;box-shadow:0 8px 32px #23395b05}.head{padding:22px 26px;display:flex;align-items:center;justify-content:space-between;gap:15px;border-bottom:1px solid #e7ecf3}.head h2{margin:0 0 7px;font-size:calc(22px + 4pt);letter-spacing:-.5px}.muted{font-size:calc(14px + 4pt);color:#68778b}.total{text-align:right;white-space:nowrap}.total .value{font-size:calc(34px + 4pt);font-weight:750;color:#155eef;letter-spacing:-1px}.total .max{font-size:calc(18px + 4pt);color:#8a98aa}.total .label{font-size:calc(12px + 4pt);text-transform:uppercase;letter-spacing:1.2px;color:#68778b;margin-top:3px}.column-head{display:flex;justify-content:space-between;padding:15px 26px 9px;font-size:calc(12px + 4pt);font-weight:600;text-transform:uppercase;letter-spacing:1.3px;color:#748298}.row{display:grid;grid-template-columns:170px 1fr 42px;align-items:center;gap:15px;padding:12px 26px;border-bottom:1px solid #eff2f6}.row:last-child{border-bottom:0}.criterion{display:flex;align-items:center;gap:13px;font-weight:600;font-size:calc(15px + 4pt)}.index{font-size:calc(12px + 4pt);color:#8190a4;font-weight:500;min-width:19px}.numbers{display:grid;grid-template-columns:repeat(10,1fr);gap:6px}.rating{height:38px;min-width:0;border:1px solid #dfe5ef;border-radius:8px;background:#f9fbfd;color:#54647a;font-size:calc(14px + 4pt);font-weight:600;transition:background .1s,transform .1s}.rating:hover{background:#eef3ff;border-color:#9dbafa}.rating[aria-checked=\"true\"]{background:#155eef;border-color:#155eef;color:white;box-shadow:0 2px 4px #155eef22}.rating:active{transform:scale(.94)}button:focus-visible{outline:3px solid #ffb020;outline-offset:3px}.row-score{text-align:right;font-size:calc(15px + 4pt);color:#a2aec0;font-weight:600}.row-score.chosen{color:#155eef}.footer{padding:18px 26px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e7ecf3;background:#fbfcfe;font-size:calc(14px + 4pt)}.progress{display:flex;gap:12px;align-items:center;color:#68778b}.track{width:100px;height:5px;background:#e5eaf2;border-radius:5px;overflow:hidden}.fill{height:100%;width:0;background:#155eef;transition:width .15s}.hint{text-align:center;color:#748298;font-size:calc(13px + 4pt);margin-top:17px}.screen-reader{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}\n@media(min-width:800px) and (max-height:850px){main{padding-top:20px}.mast{margin-bottom:18px}.tabs{margin-bottom:16px}.row{padding-top:9px;padding-bottom:9px}.head{padding-top:17px;padding-bottom:17px}}\n@media(max-width:650px){main{padding:22px 14px}.mast h1{font-size:calc(21px + 4pt)}.tab{font-size:calc(14px + 4pt);padding:12px 2px}.head{padding:20px 17px}.column-head{display:none}.row{grid-template-columns:1fr 30px;gap:12px;padding:15px 17px}.criterion{grid-column:1;grid-row:1}.row-score{grid-column:2;grid-row:1}.numbers{grid-row:2;grid-column:1/-1;gap:4px}.rating{height:39px;font-size:calc(14px + 4pt);border-radius:6px}.total .value{font-size:calc(30px + 4pt)}.footer{padding:17px}.track{width:60px}.hint{line-height:1.5}.head h2{font-size:calc(20px + 4pt)}}\n@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n\n:root{color:#1b2b33;background:#fbfbf4}body{border-top:8px solid #f9cf2e}.mast{justify-content:space-between;flex-wrap:wrap}.mark{display:none}.brand{font-weight:950;font-size:calc(22px + 4pt);letter-spacing:-1px;color:#1b2b33}.brand span{color:#087b91}.mast h1{font-size:calc(26px + 4pt);text-transform:uppercase;font-weight:900;letter-spacing:-.7px}.mast p{color:#52636a}.tabs{background:transparent;gap:8px;padding:0;border-radius:0}.tab{background:#fff;border:2px solid #1b2b33;border-radius:0;color:#1b2b33;text-transform:uppercase;font-size:calc(14px + 4pt)}.tab[aria-selected=\"true\"]{background:#f9cf2e;color:#1b2b33;box-shadow:3px 3px 0 #1b2b33}.card{border:2px solid #1b2b33;border-radius:0;box-shadow:6px 6px 0 #1b2b33}.head{background:#e8f8fc;border-bottom:2px solid #1b2b33}.head h2{font-weight:900;text-transform:uppercase}.total .value,.row-score.chosen{color:#1b2b33}.rating{border:1px solid #b8c5ca;border-radius:0;background:#fff;color:#1b2b33}.rating:hover{border-color:#1b2b33;background:#e8f8fc}.rating[aria-checked=\"true\"]{background:#26c0e2;border:2px solid #1b2b33;color:#1b2b33;box-shadow:2px 2px 0 #1b2b33}.fill{background:#26c0e2}.track{border-radius:0}.footer{flex-wrap:wrap;gap:14px;background:#fff;border-top:2px solid #1b2b33}.actions{display:flex;align-items:center;gap:18px}.button{background:#f9cf2e;border:2px solid #1b2b33;padding:12px 18px;font-weight:800;font-size:calc(14px + 4pt);text-transform:uppercase;box-shadow:3px 3px 0 #1b2b33;color:#1b2b33}.button:hover:enabled{background:#f5a031}.button:disabled{cursor:not-allowed;background:#e7ebed;color:#68777f;box-shadow:none;border-color:#b8c5ca}.button.secondary{background:white;box-shadow:none}.judge{display:flex;align-items:center;gap:12px;margin-bottom:22px;flex-wrap:wrap}.judge label{font-weight:700;font-size:calc(14px + 4pt)}.judge input{padding:11px 12px;font:inherit;border:2px solid #1b2b33;max-width:100%;width:240px;background:white;border-radius:0}.judge .note{font-size:calc(13px + 4pt);color:#52636a}.error{padding:14px;background:#fdefF5;border:2px solid #1b2b33;margin-bottom:18px}.summary-title{font-size:calc(26px + 4pt);font-weight:900;text-transform:uppercase;margin:0}.summary-panel{background:white;border:2px solid #1b2b33;box-shadow:6px 6px 0 #1b2b33;margin-bottom:24px}.summary-head{padding:24px;background:#f9cf2e;border-bottom:2px solid #1b2b33}.receipt{padding:20px 24px;background:#fdefF5;border-bottom:2px solid #1b2b33}.receipt strong{font-size:calc(24px + 4pt)}.receipt ul{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;list-style:none;padding:0;font-size:calc(14px + 4pt)}.board-wrap{overflow:auto}.board{width:100%;border-collapse:collapse}.board th{font-size:calc(12px + 4pt);letter-spacing:1px;text-transform:uppercase;text-align:left;padding:16px 24px;border-bottom:2px solid #1b2b33;white-space:nowrap}.board td{padding:17px 24px;border-bottom:1px solid #dde5e7;font-size:calc(16px + 4pt)}.board td:nth-child(3){font-weight:900}.summary-controls{padding:20px 24px;display:flex;gap:12px;flex-wrap:wrap}.summary-note{font-size:calc(14px + 4pt);margin:16px 24px;color:#52636a;line-height:1.5}.summary-count{margin:8px 0 0;font-size:calc(14px + 4pt)}.hint{color:#52636a}[hidden]{display:none!important}\n@media(max-width:650px){.mast h1{font-size:calc(22px + 4pt)}.mast{gap:16px}.tabs{gap:5px}.tab{font-size:calc(12px + 4pt)}.actions{width:100%;justify-content:space-between}.footer .progress{margin-left:auto}.receipt ul{grid-template-columns:repeat(2,1fr)}.board td,.board th{padding:14px 12px}.summary-head{padding:20px}.summary-title{font-size:calc(22px + 4pt)}.judge{gap:8px}.judge input{width:100%}.judge .note{width:100%}}\n\n.row{grid-template-columns:minmax(0,1fr) minmax(0,1.45fr) 30px;gap:18px;padding-top:18px;padding-bottom:18px}\n.criterion{align-items:flex-start;gap:12px;min-width:0}.index{padding-top:3px}.criterion-copy{min-width:0}.criterion-copy strong{display:block;line-height:1.4;font-size:calc(16px + 4pt);overflow-wrap:anywhere}.criterion-category{display:block;font-size:calc(12px + 4pt);font-weight:700;letter-spacing:.7px;text-transform:uppercase;color:#52636a;margin-bottom:4px;line-height:1.5}.criterion-description{font-weight:400;font-size:calc(14px + 4pt);line-height:1.5;color:#52636a;margin:6px 0 0}.receipt ul{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 22px;line-height:1.5}.receipt li{overflow-wrap:anywhere}\n@media(max-width:800px){.row{grid-template-columns:minmax(0,1fr) 30px;gap:12px}.criterion{grid-column:1;grid-row:1}.row-score{grid-column:2;grid-row:1}.numbers{grid-column:1/-1;grid-row:2}}\n@media(max-width:480px){.receipt ul{grid-template-columns:1fr}}\n.individual{margin:28px 24px 0;border-top:2px solid #1b2b33;padding-top:24px}.individual h3{margin:0;font-size:calc(22px + 4pt);text-transform:uppercase}.individual-intro{font-size:calc(14px + 4pt);line-height:1.5;color:#52636a;margin:8px 0 20px}.judge-team{border:2px solid #1b2b33;margin-bottom:20px}.judge-team-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;background:#e8f8fc;border-bottom:2px solid #1b2b33}.judge-team-head h4{font-size:calc(17px + 4pt);margin:0}.judge-team-total{font-size:calc(14px + 4pt);text-align:right}.judge-team-total strong{font-size:calc(19px + 4pt)}.judge-entry{border-bottom:1px solid #dde5e7}.judge-entry:last-child{border-bottom:0}.judge-entry summary{display:flex;gap:14px;align-items:center;cursor:pointer;padding:15px 16px;list-style:none}.judge-entry summary::-webkit-details-marker{display:none}.judge-entry summary::before{content:'+';font-size:calc(20px + 4pt);min-width:16px}.judge-entry[open] summary::before{content:'−'}.judge-entry summary:focus-visible{outline:3px solid #087b91;outline-offset:-3px}.judge-entry-name{flex:1;min-width:0;overflow-wrap:anywhere;font-weight:700}.judge-entry-score{white-space:nowrap;font-size:calc(14px + 4pt)}.judge-entry-score strong{font-size:calc(21px + 4pt)}.judge-breakdown{margin:0;padding:0 16px 16px 46px;list-style:none;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 24px;font-size:calc(14px + 4pt);line-height:1.5}.judge-breakdown li{display:flex;justify-content:space-between;gap:14px}.judge-breakdown li span{min-width:0;overflow-wrap:anywhere}.judge-breakdown li strong{white-space:nowrap}.judge-empty{margin:0;padding:18px 16px;color:#52636a;font-size:calc(14px + 4pt)}@media(max-width:650px){.individual{margin-left:16px;margin-right:16px}.judge-breakdown{grid-template-columns:1fr;padding-left:16px}.judge-team-head{align-items:flex-start}.judge-team-total{max-width:55%}}\n.numbers{grid-template-columns:repeat(4,1fr)}.scale-guide{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:16px;background:#e8f8fc;border:2px solid #1b2b33;font-size:calc(13px + 4pt);line-height:1.5}.scale-guide strong{display:block;font-size:calc(22px + 4pt)}.bonus-note{font-size:calc(14px + 4pt);line-height:1.5;margin:14px 0 20px;color:#52636a}@media(max-width:650px){.scale-guide{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.score-parts,.judge-score-parts{display:block;margin-top:7px;font-size:calc(12px + 4pt);font-weight:400;color:#52636a;line-height:1.5}.score-parts{white-space:normal}.judge-entry summary{flex-wrap:wrap}@media(max-width:480px){.judge-entry-score{margin-left:30px}}\n.bottom-total{display:flex;justify-content:space-between;gap:12px;padding:18px 26px;border-top:1px solid #1b2b33;background:#e8f8fc;font-size:calc(15px + 4pt)}.bottom-total span{text-align:right}@media(max-width:650px){.bottom-total{padding-left:17px;padding-right:17px}}\n.mast-actions{display:flex;gap:12px;flex-wrap:wrap}.review-head{background:#26c0e2}.review-edit{padding:9px 12px;font-size:calc(12px + 4pt);white-space:nowrap}.review-board td:nth-child(3){white-space:nowrap}.review-board tbody tr:first-child{background:#fff8d8}.final-confirmation{background:#e8f8fc;border:2px solid #1b2b33;padding:14px 18px}.review-board td:first-child{font-weight:800;white-space:nowrap}@media(max-width:650px){.mast-actions{width:100%}.review-board td,.review-board th{padding:13px 12px}}\n</style>\n</head><body>\n<main>\n<header class=\"mast\"><div><div class=\"brand\">FAST<span>FORGE</span></div><h1>Judges’ scorecard</h1><p>Pick a score from 0–3 for each rubric criterion.</p></div><div class=\"mast-actions\"><button class=\"button secondary\" id=\"review-scores\" type=\"button\" hidden>Review my ranking</button><button class=\"button secondary\" id=\"view-summary\" type=\"button\">Overall scores</button></div></header>\n<div id=\"error\" class=\"error\" role=\"alert\" hidden></div>\n<div id=\"scoring-view\">\n<div class=\"judge\"><label for=\"judge-name\">Your name</label><input id=\"judge-name\" maxlength=\"80\" autocomplete=\"name\" placeholder=\"Judge’s name\"><span class=\"note\">Added to your submitted scorecards.</span></div>\n<div class=\"scale-guide\" aria-label=\"Scoring guide\"><span><strong>0</strong> Not present</span><span><strong>1</strong> Present but unclear</span><span><strong>2</strong> Present &amp; clear</span><span><strong>3</strong> Present, clear, specific &amp; compelling</span></div>\n<p class=\"bonus-note\" id=\"bonus-budget\"></p>\n<nav class=\"tabs\" role=\"tablist\" aria-label=\"Teams\" id=\"tabs\"></nav>\n<section class=\"card\" id=\"scorecard\" role=\"tabpanel\" aria-labelledby=\"tab-0\">\n<div class=\"head\"><div><h2 id=\"team-name\">Team 1</h2><span class=\"muted\">9 rubric criteria · 27 regular points · bonus added on top</span></div><div class=\"total\"><span class=\"value\" id=\"total\">0</span><span class=\"max\"> / 27</span><div class=\"label\">Total including bonus</div><div class=\"score-parts\" id=\"score-parts\">Rubric 0 / 27 · Bonus +0</div></div></div>\n<div class=\"column-head\"><span>Rubric criterion</span><span>0 = not present · 3 = compelling</span></div>\n<div id=\"rows\"></div>\n<div class=\"bottom-total\"><strong>Total points</strong><span id=\"bottom-total\">0 / 27</span></div>\n<div class=\"footer\"><span id=\"status\">Ready to score</span><div class=\"progress\"><div class=\"track\" aria-hidden=\"true\"><div class=\"fill\" id=\"fill\"></div></div><span id=\"count\">0 / 10 scored</span></div><button class=\"button\" type=\"button\" id=\"submit\" disabled>Submit score</button></div>\n</section>\n<p class=\"hint\">Each team has its own scorecard. Switch tabs anytime.</p>\n</div>\n<section id=\"review-view\" hidden aria-labelledby=\"review-title\"><div class=\"summary-panel\"><div class=\"summary-head review-head\"><h2 class=\"summary-title\" id=\"review-title\" tabindex=\"-1\">Review your final ranking</h2><p class=\"summary-count\" id=\"review-by\"></p></div><p class=\"summary-note\" id=\"review-prompt\">You’ve scored all five teams. Are you happy with this order?</p><div class=\"board-wrap\"><table class=\"board review-board\"><thead><tr><th scope=\"col\">Rank</th><th scope=\"col\">Team</th><th scope=\"col\">Your score</th><th scope=\"col\">Edit</th></tr></thead><tbody id=\"personal-ranking\"></tbody></table></div><p class=\"summary-note\">Highest score first, including bonus points. Equal scores share the same rank.</p><div class=\"summary-controls\"><button class=\"button\" type=\"button\" id=\"confirm-ranking\">Yes, confirm final scores</button><button class=\"button secondary\" type=\"button\" id=\"edit-ranking\">Edit scores</button></div></div></section>\n<section id=\"summary-view\" hidden aria-labelledby=\"summary-title\">\n<div class=\"summary-panel\"><div class=\"summary-head\"><h2 class=\"summary-title\" id=\"summary-title\" tabindex=\"-1\">Overall scores</h2><p class=\"summary-count\" id=\"summary-count\">Loading submitted scores…</p></div>\n<p class=\"final-confirmation summary-note\" id=\"final-confirmation\" role=\"status\" hidden>Your final scores are confirmed.</p><div class=\"receipt\" id=\"receipt\" hidden></div>\n<div class=\"board-wrap\"><table class=\"board\"><thead><tr><th scope=\"col\">Team</th><th scope=\"col\">Judges</th><th scope=\"col\">Total score</th></tr></thead><tbody id=\"board\"></tbody></table></div>\n<p class=\"summary-note\">Total scores combine all submitted points, shown out of 27 × the number of judges who scored that team. Bonus points are added on top. Each judge counts once per team. Resubmitting replaces their previous score.</p>\n<section class=\"individual\" aria-labelledby=\"individual-title\"><h3 id=\"individual-title\">Scores by judge</h3><p class=\"individual-intro\">Each judge’s submitted score out of 27, grouped by team. Select a name to see their rubric scores.</p><div id=\"judge-scores\"><p class=\"judge-empty\">Loading judge scores…</p></div></section>\n<div class=\"summary-controls\"><button class=\"button\" id=\"back-scoring\" type=\"button\">Score another team</button><button class=\"button secondary\" id=\"refresh-summary\" type=\"button\">Refresh scores</button></div></div></section>\n<div id=\"announcement\" class=\"screen-reader\" aria-live=\"polite\"></div>\n</main>\n<script>\nconst roundId=\"2026-10-21-reset-1\";\nconst rubric=[{\"section\": \"Research & Ideation\", \"title\": \"Demand alignment\", \"description\": \"Identifies and conveys related product trends on Kickstarter.\"}, {\"section\": \"Research & Ideation\", \"title\": \"Customer profile\", \"description\": \"Clearly describes “THE ONE” person most likely to be the first customer in line on launch day.\"}, {\"section\": \"Product\", \"title\": \"Name and tagline\", \"description\": \"Product name (1–2 words), product title (10 words or less), and a single-sentence tagline that identifies the product and what makes it unique.\"}, {\"section\": \"Product\", \"title\": \"Product Viability\", \"description\": \"Shows existing technology and materials that prove the product can be made.\"}, {\"section\": \"Product\", \"title\": \"Key Features Definition\", \"description\": \"Identifies four or more specs to support the demand claim.\"}, {\"section\": \"Product\", \"title\": \"Differentiation\", \"description\": \"Explains why customers would choose this product over existing solutions.\"}, {\"section\": \"Presentation\", \"title\": \"Communication & Storytelling\", \"description\": \"Completes the pitch in three minutes or less, communicates clearly and enthusiastically, and tells a compelling story with a beginning, middle, and end focused on customer needs.\"}, {\"section\": \"Presentation\", \"title\": \"Prototype & Visualization\", \"description\": \"Creates a physical prototype and realistic images that convey size, shape, and basic function. Shows the design evolving from sketch to product rendering.\"}, {\"section\": \"Entrepreneurial Spirit and Teamwork\", \"title\": \"Entrepreneurial Spirit and Teamwork\", \"description\": \"Demonstrates passion, opportunity recognition, adaptability, and problem-solving in the process description and Q&A. The presentation reflects collaboration and teamwork.\"}, {\"section\": \"Bonus\", \"title\": \"Bonus Points\", \"description\": \"Award 0–3 bonus points to this team. You have 3 bonus points TOTAL across all teams, given to one team or spread across 2–3 teams.\"}];\nconst scores=Array.from({length:5},()=>Array(10).fill(null)),submitted=Array(5).fill(false);let team=0,ready=false,saving=false,confirmed=false,confirming=false;const savedBonuses=Array(5).fill(0),scaleLabels=['Not present','Present but unclear','Present & clear','Present, clear, specific & compelling'];const submit=document.getElementById('submit'),nameInput=document.getElementById('judge-name');\nconst tabs=document.getElementById('tabs'),rows=document.getElementById('rows');\nfor(let t=0;t<5;t++){const b=document.createElement('button');b.type='button';b.className='tab';b.id='tab-'+t;b.setAttribute('role','tab');b.setAttribute('aria-controls','scorecard');b.textContent='Team '+(t+1);b.addEventListener('click',()=>selectTeam(t));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(t+1)%5;if(e.key==='ArrowLeft')next=(t+4)%5;if(e.key==='Home')next=0;if(e.key==='End')next=4;if(next!==undefined){e.preventDefault();selectTeam(next);tabs.children[next].focus()}});tabs.append(b)}\nfor(let p=0;p<10;p++){const row=document.createElement('div');row.className='row';const label=document.createElement('div');label.className='criterion';label.id='point-'+p;const index=document.createElement('span');index.className='index';index.textContent=String(p+1).padStart(2,'0');const copy=document.createElement('div');copy.className='criterion-copy';const category=document.createElement('span');category.className='criterion-category';category.textContent=rubric[p].section;const title=document.createElement('strong');title.id='criterion-title-'+p;title.textContent=rubric[p].title;const description=document.createElement('p');description.className='criterion-description';description.id='criterion-description-'+p;description.textContent=rubric[p].description;copy.append(category,title,description);label.append(index,copy);const choices=document.createElement('div');choices.className='numbers';choices.setAttribute('role','radiogroup');choices.setAttribute('aria-labelledby',title.id);choices.setAttribute('aria-describedby',description.id);for(let v=0;v<=3;v++){const button=document.createElement('button');button.type='button';button.className='rating';button.textContent=v;button.dataset.value=v;button.setAttribute('role','radio');button.setAttribute('aria-label',v+' out of 3: '+(p===9?'bonus points':scaleLabels[v]));button.addEventListener('click',()=>rate(p,v));button.addEventListener('keydown',e=>{let value;if(e.key==='ArrowRight'||e.key==='ArrowDown')value=v===3?0:v+1;if(e.key==='ArrowLeft'||e.key==='ArrowUp')value=v===0?3:v-1;if(e.key==='Home')value=0;if(e.key==='End')value=3;if(value!==undefined){e.preventDefault();rate(p,value);choices.children[value].focus()}});choices.append(button)}const selected=document.createElement('div');selected.className='row-score';selected.setAttribute('aria-hidden','true');row.append(label,choices,selected);rows.append(row)}\nfunction selectTeam(t){team=t;render()}\nfunction rate(p,v){if(p===9&&v>3-savedBonuses.reduce((sum,bonus,t)=>sum+(t===team?0:bonus),0))return;scores[team][p]=v;submitted[team]=false;confirmed=false;render();document.getElementById('announcement').textContent='Team '+(team+1)+', '+rubric[p].title+': '+v+' out of 3. Total '+scores[team].reduce((s,x)=>s+(x||0),0)+' out of 27.'}\nfunction render(){for(let t=0;t<5;t++){tabs.children[t].disabled=saving;tabs.children[t].setAttribute('aria-selected',t===team);tabs.children[t].tabIndex=t===team?0:-1}document.getElementById('scorecard').setAttribute('aria-labelledby','tab-'+team);document.getElementById('team-name').textContent='Team '+(team+1);let total=0,count=0;for(let p=0;p<10;p++){const value=scores[team][p],row=rows.children[p];if(value!==null){total+=value;count++}for(const b of row.children[1].children){const selected=Number(b.dataset.value)===value;b.disabled=saving||(p===9&&Number(b.dataset.value)>3-savedBonuses.reduce((sum,bonus,t)=>sum+(t===team?0:bonus),0));b.setAttribute('aria-checked',selected);b.tabIndex=selected||(value===null&&b.dataset.value==='0')?0:-1}row.children[2].textContent=value===null?'—':value;row.children[2].classList.toggle('chosen',value!==null)}document.getElementById('total').textContent=total;document.getElementById('score-parts').textContent='Rubric '+scores[team].slice(0,9).reduce((sum,x)=>sum+(x||0),0)+' / 27 · Bonus +'+(scores[team][9]||0);document.getElementById('count').textContent=count+' / 10 scored';document.getElementById('fill').style.width=(count*10)+'%';document.getElementById('status').textContent=submitted[team]?'Score submitted':count===10?'Ready to submit':count===0?'Ready to score':(10-count)+' criteria remaining';document.getElementById('bottom-total').textContent=total+' / 27 · Bonus +'+(scores[team][9]||0)+' included';nameInput.disabled=saving;document.getElementById('view-summary').disabled=saving;const otherBonus=savedBonuses.reduce((sum,bonus,t)=>sum+(t===team?0:bonus),0),bonusFits=otherBonus+(scores[team][9]||0)<=3;document.getElementById('bonus-budget').textContent='Bonus budget: '+(3-otherBonus)+' of 3 points available for this team, based on your other submitted scorecards.';submit.disabled=!ready||saving||count!==10||!nameInput.value.trim()||!bonusFits;submit.textContent=saving?'Submitting…':submitted[team]?'Update score':'Submit score';const reviewButton=document.getElementById('review-scores');reviewButton.hidden=!submitted.every(Boolean);reviewButton.disabled=saving||confirming;document.getElementById('confirm-ranking').disabled=confirming;document.getElementById('confirm-ranking').textContent=confirming?'Confirming…':confirmed?'Continue to leaderboard':'Yes, confirm final scores';document.getElementById('edit-ranking').disabled=confirming;document.getElementById('view-summary').disabled=saving||confirming}\n\nfunction showError(message){const e=document.getElementById('error');e.textContent=message;e.hidden=!message}\nasync function api(path,options){const r=await fetch(path,options);const data=await r.json();if(!r.ok)throw new Error(data.error||'Could not load scores. Please try again.');return data}\nasync function loadSummary(){const button=document.getElementById('refresh-summary');button.disabled=true;try{const data=await api('/api/summary');document.getElementById('summary-count').textContent=data.judges+' '+(data.judges===1?'judge has':'judges have')+' submitted scores';const board=document.getElementById('board');board.replaceChildren();for(const t of [...data.teams].sort((a,b)=>b.total-a.total||a.team-b.team)){const row=document.createElement('tr');for(const value of ['Team '+t.team,t.judges,t.total+' / '+(27*t.judges)]){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}board.append(row)}renderJudgeScores(data.teams);showError('')}catch(e){showError(e.message)}finally{button.disabled=false}}\nfunction renderJudgeScores(teams){const container=document.getElementById('judge-scores');container.replaceChildren();for(const team of [...teams].sort((a,b)=>a.team-b.team)){const section=document.createElement('section');section.className='judge-team';const head=document.createElement('div');head.className='judge-team-head';const title=document.createElement('h4');title.textContent='Team '+team.team;const total=document.createElement('div');total.className='judge-team-total';const points=document.createElement('strong');points.textContent=team.total+' / '+(27*team.judges);total.append(points,document.createTextNode(' combined points · '+team.judges+' '+(team.judges===1?'judge':'judges')));head.append(title,total);section.append(head);if(!team.scores.length){const empty=document.createElement('p');empty.className='judge-empty';empty.textContent='No scores submitted for this team yet.';section.append(empty)}for(const score of team.scores){const entry=document.createElement('details');entry.className='judge-entry';const summary=document.createElement('summary');const name=document.createElement('span');name.className='judge-entry-name';name.textContent=score.name;const value=document.createElement('span');value.className='judge-entry-score';const points=document.createElement('strong');points.textContent=score.total;value.append(points,document.createTextNode(' / 27'));const parts=document.createElement('span');parts.className='judge-score-parts';parts.textContent='Rubric '+score.ratings.slice(0,9).reduce((sum,x)=>sum+x,0)+' / 27 · Bonus +'+score.ratings[9];value.append(parts);summary.append(name,value);const list=document.createElement('ul');list.className='judge-breakdown';score.ratings.forEach((rating,i)=>{const item=document.createElement('li');const label=document.createElement('span');label.textContent=rubric[i].title;const number=document.createElement('strong');number.textContent=i===9?'+'+rating+' bonus':rating+' / 3';item.append(label,number);list.append(item)});entry.append(summary,list);section.append(entry)}container.append(section)}}\nfunction summary(){if(submitted.every(Boolean)&&!confirmed){showReview();return}document.getElementById('review-view').hidden=true;document.getElementById('final-confirmation').hidden=!confirmed;document.getElementById('scoring-view').hidden=true;document.getElementById('summary-view').hidden=false;document.getElementById('summary-title').focus();loadSummary()}\nnameInput.addEventListener('input',render);\n\ndocument.getElementById('view-summary').addEventListener('click',()=>{document.getElementById('receipt').hidden=true;summary()});\ndocument.getElementById('refresh-summary').addEventListener('click',loadSummary);\ndocument.getElementById('back-scoring').addEventListener('click',()=>{const next=submitted.findIndex(x=>!x);editTeam(next===-1?team:next)});\nfunction editTeam(t){if(confirming)return;document.getElementById('review-view').hidden=true;document.getElementById('summary-view').hidden=true;document.getElementById('scoring-view').hidden=false;showError('');selectTeam(t);tabs.children[t].focus()}\nfunction showReview(){if(!submitted.every(Boolean))return;document.getElementById('scoring-view').hidden=true;document.getElementById('summary-view').hidden=true;document.getElementById('review-view').hidden=false;document.getElementById('review-by').textContent='Your scores · '+nameInput.value.trim();document.getElementById('review-prompt').textContent=confirmed?'Your final scores are confirmed. You can still edit a team and confirm again.':'You’ve scored all five teams. Are you happy with this order?';const ranking=scores.map((ratings,t)=>({team:t,total:ratings.reduce((a,b)=>a+b,0)})).sort((a,b)=>b.total-a.total||a.team-b.team);const board=document.getElementById('personal-ranking');board.replaceChildren();ranking.forEach((score,i)=>{const row=document.createElement('tr');const rank=ranking.findIndex(x=>x.total===score.total)+1;const tied=ranking.filter(x=>x.total===score.total).length>1;for(const value of [rank+(tied?' (tie)':''),'Team '+(score.team+1),score.total+' / 27']){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}const action=document.createElement('td');const edit=document.createElement('button');edit.type='button';edit.className='button secondary review-edit';edit.textContent='Edit score';edit.setAttribute('aria-label','Edit Team '+(score.team+1)+' score');edit.addEventListener('click',()=>editTeam(score.team));action.append(edit);row.append(action);board.append(row)});render();document.getElementById('review-title').focus();showError('')}\ndocument.getElementById('review-scores').addEventListener('click',showReview);\ndocument.getElementById('edit-ranking').addEventListener('click',()=>editTeam(team));\ndocument.getElementById('confirm-ranking').addEventListener('click',async()=>{if(confirming||!submitted.every(Boolean))return;confirming=true;showError('');render();try{await api('/api/finalize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({roundId,ballots:scores.map((ratings,t)=>({team:t+1,ratings}))})});confirmed=true;document.getElementById('receipt').hidden=true;summary()}catch(e){showError(e.message)}finally{confirming=false;render()}});\nsubmit.addEventListener('click',async()=>{if(submit.disabled)return;const t=team,ratings=[...scores[t]],name=nameInput.value.trim();saving=true;showError('');render();try{const data=await api('/api/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({team:t+1,ratings,name,roundId,scoringVersion:2})});submitted[t]=true;confirmed=false;savedBonuses[t]=ratings[9];const receipt=document.getElementById('receipt');receipt.replaceChildren();const title=document.createElement('strong');title.textContent='Team '+data.team+' submitted: '+data.total+' / 27';const by=document.createElement('p');by.textContent='Your scorecard · '+data.name+' · Rubric '+data.ratings.slice(0,9).reduce((sum,x)=>sum+x,0)+' / 27 · Bonus +'+data.ratings[9];const list=document.createElement('ul');data.ratings.forEach((score,i)=>{const li=document.createElement('li');li.textContent=rubric[i].title+': '+(i===9?'+'+score+' bonus':score+' / 3');list.append(li)});receipt.append(title,by,list);receipt.hidden=false;summary()}catch(e){showError(e.message)}finally{saving=false;render()}});\nasync function initialize(){try{const data=await api('/api/session');if(data.legacyName)nameInput.value=data.legacyName;for(const ballot of data.ballots){const t=ballot.team-1;const ratings=JSON.parse(ballot.ratings);if(t>=0&&t<5&&ratings.length===10&&ratings.every(x=>Number.isInteger(x)&&x>=0&&x<=3)){scores[t]=ratings;savedBonuses[t]=ratings[9];submitted[t]=true;nameInput.value=ballot.judge_name}}confirmed=!!data.confirmed;ready=true;render();if(submitted.every(Boolean))showReview()}catch(e){showError(e.message);document.getElementById('status').textContent='Unable to connect';const retry=document.createElement('button');retry.className='button secondary';retry.type='button';retry.textContent='Reconnect';retry.addEventListener('click',()=>{retry.remove();initialize()});document.getElementById('error').append(document.createTextNode(' '),retry)}}\nrender();initialize();\n</script>\n</body></html>\n";
const FAVICON="<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><rect x=\"2\" y=\"2\" width=\"60\" height=\"60\" fill=\"#f9cf2e\" stroke=\"#1b2b33\" stroke-width=\"4\"/><path d=\"m18 33 9 9 19-21\" fill=\"none\" stroke=\"#1b2b33\" stroke-width=\"7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n";
const CURRENT_ROUND='2026-10-21-reset-1';
function json(data,status=200,extra={}){return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store',...extra}})}
function database(env){if(!env.DB)throw new Error('Score database unavailable');return env.DB}
function scoreSnapshot(ballots){return JSON.stringify([...ballots].sort((a,b)=>a.team-b.team).map(x=>({team:x.team,ratings:typeof x.ratings==='string'?JSON.parse(x.ratings):x.ratings})))}
function cookieJudge(request){const value=request.headers.get('cookie')?.match(/(?:^|;\s*)ff_judge=([a-f0-9-]{36})(?:;|$)/)?.[1];return value||null}
export default {async fetch(request,env){
  const url=new URL(request.url),path=url.pathname;
  if(path==='/favicon.svg')return new Response(FAVICON,{headers:{'Content-Type':'image/svg+xml'}});
  if(path==='/'&&request.method==='GET')return new Response(HTML,{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-cache'}});
  try{
    if(path==='/api/session'&&request.method==='GET'){
      const existing=cookieJudge(request),id=existing||crypto.randomUUID();
      const mine=await database(env).prepare('SELECT team, judge_name, ratings, total FROM ballots WHERE judge_id = ? AND scoring_version = 2 AND round_id = ?').bind(id,CURRENT_ROUND).all();
      const legacy=await database(env).prepare('SELECT COUNT(*) AS count, MAX(judge_name) AS name FROM ballots WHERE judge_id = ? AND scoring_version = 1 AND round_id = ?').bind(id,CURRENT_ROUND).first();
      const review=await database(env).prepare('SELECT score_snapshot FROM judge_reviews WHERE judge_id = ? AND round_id = ?').bind(id,CURRENT_ROUND).first();
      return json({confirmed:mine.results.length===5&&review?.score_snapshot===scoreSnapshot(mine.results),ballots:mine.results,legacyCount:legacy.count,legacyName:legacy.name},200,existing?{}:{'Set-Cookie':`ff_judge=${id}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=31536000`});
    }
    if(path==='/api/summary'&&request.method==='GET'){
      const result=await database(env).prepare('SELECT team, COUNT(*) AS judges, SUM(total) AS total, ROUND(AVG(total), 1) AS average FROM ballots WHERE scoring_version = 2 AND round_id = ? GROUP BY team ORDER BY team').bind(CURRENT_ROUND).all();
      const count=await database(env).prepare('SELECT COUNT(DISTINCT judge_id) AS judges FROM ballots WHERE scoring_version = 2 AND round_id = ?').bind(CURRENT_ROUND).first();
      const ballots=await database(env).prepare('SELECT team, judge_name, ratings, total FROM ballots WHERE scoring_version = 2 AND round_id = ? ORDER BY judge_name COLLATE NOCASE, updated_at').bind(CURRENT_ROUND).all();
      const legacy=await database(env).prepare('SELECT COUNT(*) AS count FROM ballots WHERE scoring_version = 1 AND round_id = ?').bind(CURRENT_ROUND).first();
      return json({legacyCount:legacy.count,teams:Array.from({length:5},(_,i)=>({...result.results.find(x=>x.team===i+1)||{team:i+1,judges:0,total:0,average:0},scores:ballots.results.filter(x=>x.team===i+1).map(x=>({name:x.judge_name,total:x.total,ratings:JSON.parse(x.ratings)}))})),judges:count.judges});
    }
    if(path==='/api/finalize'&&request.method==='POST'){
      if(request.headers.get('origin')!==url.origin)return json({error:'Please confirm from this scorecard.'},403);
      const id=cookieJudge(request);if(!id)return json({error:'Reload the page to reconnect your judge session.'},401);
      if(Number(request.headers.get('content-length')||0)>16384)return json({error:'Confirmation too large.'},413);
      let body;try{body=await request.json()}catch{return json({error:'Invalid confirmation.'},400)}
      if(body?.roundId!==CURRENT_ROUND)return json({error:'The scorecard has been reset. Reload the page.'},409);
      const ballots=await database(env).prepare('SELECT team, ratings FROM ballots WHERE judge_id = ? AND round_id = ? AND scoring_version = 2 ORDER BY team').bind(id,CURRENT_ROUND).all();
      if(ballots.results.length!==5)return json({error:'Save a scorecard for all five teams before confirming.'},400);
      const expected=scoreSnapshot(ballots.results);
      if(!Array.isArray(body.ballots)||body.ballots.length!==5||body.ballots.some(x=>!x||!Number.isInteger(x.team)||!Array.isArray(x.ratings))||scoreSnapshot(body.ballots)!==expected)return json({error:'Your saved scores have changed. Reload to review the latest scores before confirming.'},409);
      await database(env).prepare('INSERT INTO judge_reviews (judge_id, round_id, score_snapshot, confirmed_at) VALUES (?, ?, ?, ?) ON CONFLICT(judge_id, round_id) DO UPDATE SET score_snapshot = excluded.score_snapshot, confirmed_at = excluded.confirmed_at').bind(id,CURRENT_ROUND,expected,new Date().toISOString()).run();
      return json({confirmed:true});
    }
    if(path==='/api/submit'&&request.method==='POST'){
      if(request.headers.get('origin')!==url.origin)return json({error:'Please submit from this scorecard.'},403);
      const id=cookieJudge(request);if(!id)return json({error:'Reload the page to reconnect your judge session.'},401);
      if(Number(request.headers.get('content-length')||0)>16384)return json({error:'Submission too large.'},413);
      let body;try{body=await request.json()}catch{return json({error:'Invalid scorecard.'},400)}
      if(body.roundId!==CURRENT_ROUND)return json({error:'The scorecard has been reset. Reload the page to start a new scorecard.'},409);
      if(body.scoringVersion!==2)return json({error:'The rubric now uses 0–3. Reload this page and score again.'},409);
      const {team,ratings}=body,name=typeof body.name==='string'?body.name.trim():'';
      if(!Number.isInteger(team)||team<1||team>5||!Array.isArray(ratings)||ratings.length!==10||ratings.some(x=>!Number.isInteger(x)||x<0||x>3)||!name||name.length>80)return json({error:'Enter your name and fill all ten scores from 0–3.'},400);
      const total=ratings.reduce((a,b)=>a+b,0);
      const saved=await database(env).prepare("INSERT INTO ballots (judge_id, team, judge_name, ratings, total, updated_at, scoring_version, round_id) SELECT ?, ?, ?, ?, ?, ?, 2, ? WHERE COALESCE((SELECT SUM(CAST(json_extract(ratings, '$[9]') AS INTEGER)) FROM ballots WHERE judge_id = ? AND team <> ? AND scoring_version = 2 AND round_id = ?), 0) + ? <= 3 ON CONFLICT(judge_id, team) DO UPDATE SET judge_name = excluded.judge_name, ratings = excluded.ratings, total = excluded.total, updated_at = excluded.updated_at, scoring_version = excluded.scoring_version, round_id = excluded.round_id").bind(id,team,name,JSON.stringify(ratings),total,new Date().toISOString(),CURRENT_ROUND,id,team,CURRENT_ROUND,ratings[9]).run();
      if(Number(saved.meta?.changes??saved.changes)!==1)return json({error:'You have only 3 bonus points across all teams. Reduce this bonus or update another team’s submitted bonus first.'},409);
      return json({team,total,ratings,name});
    }
    return json({error:'Not found.'},404);
  }catch(error){console.error('Scorecard request failed',path,error);return json({error:'Scores are temporarily unavailable. Your selections are still here; please try again.'},503)}
}};
